const now = Date.now();
const minute = 60 * 1000;
const day = 24 * 60 * minute;

function kstDate(ms, offset = 0) {
  return new Date(ms + 9 * 60 * minute + offset * day)
    .toISOString().slice(0, 10);
}

function createJob(id, name, type, offset, extra = {}) {
  const sendAt = now + offset * minute;

  return {
    json: {
      job_id: id,
      schedule_id: id,
      test_case: name,
      mode: 'mock',
      notification_type: type,
      occurrence_date: kstDate(
        sendAt, type === 'd1' ? 1 : 0
      ),
      send_at: new Date(sendAt).toISOString(),
      checked_at: new Date(now).toISOString(),
      timezone: 'Asia/Seoul',
      recipient_email: 'test@example.test',
      consent: true,
      type_enabled: true,
      status: 'pending',
      schedule_revision: 1,
      current_revision: 1,
      expected_eligible: true,
      ...extra
    }
  };
}

return [
  createJob(1, 'D-1 정상 알림', 'd1', -0.5),

  createJob(2, '당일 정상 알림', 'day_of', -0.5),

  createJob(3, '알림 미동의', 'd1', -1, {
    consent: false,
    expected_eligible: false
  }),

  createJob(4, '발송 시간 미도달', 'day_of', 30, {
    expected_eligible: false
  }),

  createJob(5, '이미 발송된 알림', 'd1', -1, {
    status: 'sent',
    expected_eligible: false
  }),

  createJob(6, '발송 허용 시간 초과', 'day_of', -11, {
    expected_eligible: false
  }),

  createJob(7, '일정 수정으로 무효화', 'd1', -1, {
    current_revision: 2,
    expected_eligible: false
  }),

  createJob(8, '알림 종류 비활성화', 'day_of', -1, {
    type_enabled: false,
    expected_eligible: false
  })
];

return $input.all().map(item => {
  const job = item.json;
  const reasons = [];

  const now = Date.parse(job.checked_at);
  const sendAt = Date.parse(job.send_at);
  const elapsed = now - sendAt;

  if (job.mode !== 'mock') {
    reasons.push('테스트 데이터 아님');
  }

  if (job.consent !== true) {
    reasons.push('알림 미동의');
  }

  if (job.type_enabled !== true) {
    reasons.push('알림 종류 비활성화');
  }

  if (job.status !== 'pending') {
    reasons.push('발송 대기 상태 아님');
  }

  if (job.schedule_revision !== job.current_revision) {
    reasons.push('일정 변경으로 무효화');
  }

  if (!Number.isFinite(elapsed)) {
    reasons.push('잘못된 시간 정보');
  } else if (elapsed < 0) {
    reasons.push('발송 시간 미도달');
  } else if (elapsed > 10 * 60 * 1000) {
    reasons.push('발송 허용 시간 초과');
  }

  const eligible = reasons.length === 0;

  return {
    json: {
      ...job,
      eligible,
      reason: eligible
        ? '발송 조건 충족'
        : reasons.join(', '),
      test_result: eligible === job.expected_eligible
        ? 'PASS'
        : 'FAIL'
    }
  };
});

return $input.all().map(item => {
  const job = item.json;

  const allowed =
    job.mode === 'mock' &&
    job.eligible === true &&
    job.consent === true &&
    job.recipient_email === 'test@example.test' &&
    ['d1', 'day_of'].includes(job.notification_type);

  const message = job.notification_type === 'd1'
    ? '내일은 함께 등록한 일정이 있는 날이에요!'
    : '오늘은 함께 등록한 일정이 있는 날이에요!';

  return {
    json: {
      job_id: job.job_id,
      test_case: job.test_case,
      notification_type: job.notification_type,
      occurrence_date: job.occurrence_date,
      recipient_email: job.recipient_email,
      subject: '[TWO PICK] 커플 일정 알림',
      message: allowed ? message : '',
      mode: 'mock',
      delivery_status: allowed
        ? 'SIMULATED_SUCCESS'
        : 'BLOCKED',
      actual_email_sent: false,
      processed_at: new Date().toISOString(),
      test_result: allowed ? 'PASS' : 'FAIL'
    }
  };
});

return $input.all().map(item => {
  const job = item.json;

  const passed =
    job.mode === 'mock' &&
    job.eligible === false &&
    job.expected_eligible === false &&
    job.test_result === 'PASS' &&
    typeof job.reason === 'string' &&
    job.reason.trim() !== '';

  return {
    json: {
      job_id: job.job_id,
      test_case: job.test_case,
      notification_type: job.notification_type,
      mode: 'mock',
      delivery_status: 'BLOCKED',
      blocked_reason: job.reason,
      actual_email_sent: false,
      processed_at: new Date().toISOString(),
      test_result: passed ? 'PASS' : 'FAIL'
    }
  };
});

const rows = $input.all().map(item => item.json);

const total = rows.length;
const passed = rows.filter(
  r => r.test_result === 'PASS'
).length;

const simulated = rows.filter(
  r => r.delivery_status === 'SIMULATED_SUCCESS'
).length;

const blocked = rows.filter(
  r => r.delivery_status === 'BLOCKED'
).length;

const actualSent = rows.filter(
  r => r.actual_email_sent === true
).length;

const uniqueJobs = new Set(
  rows.map(r => r.job_id)
).size;

const success =
  total === 8 &&
  uniqueJobs === 8 &&
  passed === 8 &&
  simulated === 2 &&
  blocked === 6 &&
  rows.every(r => r.actual_email_sent === false);

return [{
  json: {
    service: 'TWO PICK',
    workflow: '02 Notification Scheduler',
    mode: 'mock',
    timezone: 'Asia/Seoul',
    total_tests: total,
    passed_tests: passed,
    failed_tests: total - passed,
    pass_rate: total
      ? `${(passed / total * 100).toFixed(1)}%`
      : '0%',
    simulated_deliveries: simulated,
    blocked_notifications: blocked,
    actual_emails_sent: actualSent,
    unique_jobs: uniqueJobs,
    overall_result: success ? 'PASS' : 'FAIL',
    completed_at: new Date().toISOString(),
    details: rows.map(r => ({
      job_id: r.job_id,
      test_case: r.test_case,
      delivery_status: r.delivery_status,
      test_result: r.test_result
    }))
  }
}];
